class Solution {
public:
    int minCost(string colors, vector<int>& neededTime) {
        int n = colors.size();
        int totalCost = 0;
        int i = 0;
        while (i < n) {
            int j = i;
            int sum = 0;
            int maxTime = 0;
            while (j < n && colors[j] == colors[i]) {
                sum += neededTime[j];
                maxTime = max(maxTime, neededTime[j]);
                j++;
            }
            totalCost += sum - maxTime;
            i = j;
        }
        return totalCost;
    }
};
